//! Fixture parity tests for the Fish S1 DAC port.
//!
//! Fixtures live in `testdata/fish_s1_dac/`, regenerated by
//! `tools/gen_fish_s1_dac_fixtures.py` against the pinned mlx-audio
//! commit (tiny mirrored geometry of `build_ae()`; the transformers'
//! `freqs_cis` and causal masks stay at their true init values and are
//! recomputed, never loaded). Gates: encode codes per book and the
//! decoded waveforms, plus a random-codes decode. A real checkpoint
//! directory can be pointed at via TURBOSPARK_FISH_S1_DAC_MODEL and is
//! skipped when absent. Tests never download.

use std::path::{Path, PathBuf};

use super::{FishS1Dac, FishS1DacConfig};
use turbospark_model_io::safetensors::SafetensorsFile;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/fish_s1_dac")
        .join(name)
}

fn read_json(name: &str) -> serde_json::Value {
    let text = std::fs::read_to_string(testdata(name)).expect(name);
    serde_json::from_str(&text).expect(name)
}

fn read_npy(name: &str) -> (Vec<usize>, Vec<f32>) {
    let bytes = std::fs::read(testdata(name)).expect(name);
    assert_eq!(&bytes[..6], b"\x93NUMPY");
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    let header = std::str::from_utf8(&bytes[10..10 + header_len]).unwrap();
    let start = header.find('(').unwrap() + 1;
    let end = header[start..].find(')').unwrap() + start;
    let shape: Vec<usize> = header[start..end]
        .split(',')
        .filter_map(|p| p.trim().parse::<usize>().ok())
        .collect();
    let data = bytes[10 + header_len..]
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    (shape, data)
}

/// Codes arrive as int32 npy, rows are books.
fn read_codes(name: &str) -> Vec<Vec<i32>> {
    let bytes = std::fs::read(testdata(name)).expect(name);
    assert_eq!(&bytes[..6], b"\x93NUMPY");
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    let header = std::str::from_utf8(&bytes[10..10 + header_len]).unwrap();
    assert!(header.contains("<i4"), "{name} must be int32");
    let start = header.find('(').unwrap() + 1;
    let end = header[start..].find(')').unwrap() + start;
    let shape: Vec<usize> = header[start..end]
        .split(',')
        .filter_map(|p| p.trim().parse::<usize>().ok())
        .collect();
    assert_eq!(shape.len(), 2, "{name} must be [books, T]");
    let (books, frames) = (shape[0], shape[1]);
    let data: Vec<i32> = bytes[10 + header_len..]
        .chunks_exact(4)
        .map(|c| i32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    (0..books)
        .map(|b| data[b * frames..(b + 1) * frames].to_vec())
        .collect()
}

fn rel_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(a.len(), b.len());
    let max = b.iter().fold(0.0f32, |acc, v| acc.max(v.abs()));
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
        / max
}

fn load_tiny() -> FishS1Dac {
    let config = read_json("tiny_config.json");
    let config = FishS1DacConfig::from_json(&config).expect("config");
    let file = SafetensorsFile::open(&testdata("tiny_weights.safetensors")).expect("weights");
    FishS1Dac::load(config, &file).expect("load")
}

#[test]
fn config_defaults_match_build_ae() {
    let config = FishS1DacConfig::build_ae();
    assert_eq!(config.sample_rate, 44_100);
    assert_eq!(config.encoder_dim, 64);
    assert_eq!(config.encoder_rates, vec![2, 4, 8, 8]);
    assert_eq!(config.latent_dim, 1024);
    assert_eq!(config.decoder_dim, 1536);
    assert_eq!(config.decoder_rates, vec![8, 8, 4, 2]);
    assert_eq!(config.encoder_transformer_layers, vec![0, 0, 0, 4]);
    assert_eq!(config.hop_length(), 512);
    assert_eq!(config.frame_length(), 2048);
    assert_eq!(config.quantizer.n_codebooks, 9);
    assert_eq!(config.quantizer.semantic_codebook_size, 4096);
    assert_eq!(config.quantizer.codebook_size, 1024);
    assert_eq!(config.quantizer.codebook_dim, 8);
    assert_eq!(config.quantizer.downsample_factor, vec![2, 2]);
    assert_eq!(config.total_books(), 10);
    // The pre/post transformer windows come from build_ae.
    assert_eq!(config.quantizer.pre.window_size, 128);
    assert_eq!(config.quantizer.pre.n_head, 16);
}

#[test]
fn encode_decode_matches_reference() {
    let model = load_tiny();
    let traces = read_json("traces.json");
    for tag in ["a", "b"] {
        let (_, wave) = read_npy(&format!("{tag}_wave.npy"));
        let (codes, code_len) = model.encode(&wave).unwrap();
        let golden = read_codes(&format!("{tag}_codes.npy"));
        assert_eq!(codes.len(), golden.len(), "tag {tag} book count");
        for (b, (mine, gold)) in codes.iter().zip(&golden).enumerate() {
            assert_eq!(mine, gold, "tag {tag} book {b}");
        }
        assert_eq!(
            code_len as i64,
            traces[format!("{tag}_codes_shape").as_str()]
                .as_array()
                .unwrap()[1]
                .as_i64()
                .unwrap()
        );
        let (_, golden_wave) = read_npy(&format!("{tag}_decoded.npy"));
        let audio = model.decode(&codes).unwrap();
        assert_eq!(audio.len(), golden_wave.len());
        // The tiny stack amplifies; relative gate as in the sibling
        // fixture families.
        let rel = rel_diff(&audio, &golden_wave);
        assert!(rel < 1e-3, "tag {tag} decoded rel diff {rel}");
        assert_eq!(
            audio.len(),
            code_len * model.config.frame_length(),
            "tag {tag} length"
        );
    }
}

#[test]
fn random_codes_decode_matches_reference() {
    let model = load_tiny();
    let codes = read_codes("rand_codes.npy");
    let (_, golden) = read_npy("rand_decoded.npy");
    let audio = model.decode(&codes).unwrap();
    assert_eq!(audio.len(), golden.len());
    let rel = rel_diff(&audio, &golden);
    assert!(rel < 1e-3, "rand decode rel diff {rel}");
}

#[test]
fn decode_validates_books() {
    let model = load_tiny();
    let too_few = vec![vec![0i32; 2]];
    assert!(model.decode(&too_few).is_err());
    // Out-of-range semantic code (16-entry book).
    let mut bad = read_codes("rand_codes.npy");
    bad[0][0] = 99;
    assert!(model.decode(&bad).is_err());
}

/// Real-checkpoint gate; opt-in via TURBOSPARK_FISH_S1_DAC_MODEL
/// pointing at a directory with model.safetensors (config.json
/// optional; geometry defaults to build_ae). Skips when unset.
#[test]
fn real_checkpoint_gate() {
    let Ok(dir) = std::env::var("TURBOSPARK_FISH_S1_DAC_MODEL") else {
        eprintln!("skipping: TURBOSPARK_FISH_S1_DAC_MODEL not set");
        return;
    };
    let model = FishS1Dac::open(Path::new(&dir)).unwrap();
    let n = model.config.frame_length() * 2;
    let wave: Vec<f32> = (0..n)
        .map(|i| ((i as f32) * 220.0 * std::f32::consts::TAU / 44_100.0).sin() * 0.2)
        .collect();
    let (codes, code_len) = model.encode(&wave).unwrap();
    assert_eq!(code_len, 2);
    assert_eq!(codes.len(), model.config.total_books());
    let audio = model.decode(&codes).unwrap();
    assert_eq!(audio.len(), n);
    assert!(audio.iter().all(|v| v.is_finite()));
}

#[test]
fn encode_zq_decode_zq_roundtrip_matches_shapes() {
    let model = load_tiny();
    let traces = read_json("traces.json");
    for tag in ["a", "b"] {
        let (_, wave) = read_npy(&format!("{tag}_wave.npy"));
        let (zq, frames) = model.encode_zq(&wave).unwrap();
        // The continuous latents sit at the downsampled code rate.
        assert_eq!(
            frames,
            wave.len() / model.config.frame_length(),
            "tag {tag} zq frames"
        );
        assert_eq!(zq.len(), frames * model.config.latent_dim);
        // The codes path sees the same frame count.
        let (codes, code_len) = model.encode(&wave).unwrap();
        assert_eq!(code_len, frames);
        assert_eq!(codes[0].len(), frames);
        // Deterministic.
        let (zq2, frames2) = model.encode_zq(&wave).unwrap();
        assert_eq!(zq, zq2);
        assert_eq!(frames, frames2);
        let _ = traces[format!("{tag}_codes_shape").as_str()].clone();
        // decode_zq of the continuous latents returns the full waveform.
        let audio = model.decode_zq(&zq, frames).unwrap();
        assert_eq!(audio.len(), frames * model.config.frame_length());
        assert!(audio.iter().all(|v| v.is_finite()));
    }
}

#[test]
fn decode_zq_validates_lengths() {
    let model = load_tiny();
    let frames = 2;
    let latent_dim = model.config.latent_dim;
    let zq = vec![0.01f32; frames * latent_dim];
    assert!(model.decode_zq(&zq, frames).is_ok());
    assert!(model.decode_zq(&zq[..zq.len() - 1], frames).is_err());
    assert!(model.decode_zq(&zq, frames + 1).is_err());
}

/// Which raw-PyTorch spelling [`renamed_fixture`] writes.
#[derive(Clone, Copy)]
enum TorchLayout {
    /// `P.conv.parametrizations.weight.original0/1` with the bias at
    /// `P.conv.bias`: Drama 3's `codec.safetensors`.
    ConvHop,
    /// `P.parametrizations.weight.original0/1` with the bias at `P.bias`.
    Bare,
}

/// Rewrites the tiny fixture's conv weight-norm triples into a raw
/// PyTorch spelling. The quantizer `in_proj`/`out_proj` pairs stay in the
/// MLX spelling, the same mix Drama 3's export has. Only the header is
/// renamed, so tensor bytes and offsets are the fixture's own.
fn renamed_fixture(layout: TorchLayout) -> (PathBuf, usize) {
    let bytes = std::fs::read(testdata("tiny_weights.safetensors")).expect("fixture");
    let header_len = u64::from_le_bytes(bytes[..8].try_into().unwrap()) as usize;
    let header: serde_json::Map<String, serde_json::Value> =
        serde_json::from_slice(&bytes[8..8 + header_len]).expect("header");
    let wn_prefixes: std::collections::BTreeSet<String> = header
        .keys()
        .filter_map(|n| n.strip_suffix(".weight_v"))
        .filter(|p| !p.ends_with(".in_proj") && !p.ends_with(".out_proj"))
        .map(str::to_string)
        .collect();
    let hop = match layout {
        TorchLayout::ConvHop => ".conv",
        TorchLayout::Bare => "",
    };
    let mut renamed = serde_json::Map::new();
    let mut count = 0;
    for (name, value) in header {
        let (prefix, leaf) = name.rsplit_once('.').unwrap_or(("", &name));
        let new_name = if wn_prefixes.contains(prefix) {
            match leaf {
                "weight_g" => format!("{prefix}{hop}.parametrizations.weight.original0"),
                "weight_v" => format!("{prefix}{hop}.parametrizations.weight.original1"),
                "bias" => format!("{prefix}{hop}.bias"),
                _ => name.clone(),
            }
        } else {
            name.clone()
        };
        count += usize::from(new_name != name);
        assert!(
            renamed.insert(new_name.clone(), value).is_none(),
            "rename collided on {new_name}"
        );
    }
    let json = serde_json::to_vec(&serde_json::Value::Object(renamed)).unwrap();
    let mut out = (json.len() as u64).to_le_bytes().to_vec();
    out.extend_from_slice(&json);
    out.extend_from_slice(&bytes[8 + header_len..]);
    let tag = match layout {
        TorchLayout::ConvHop => "conv_hop",
        TorchLayout::Bare => "bare",
    };
    let path = std::env::temp_dir().join(format!(
        "fish_s1_dac_{tag}_{}.safetensors",
        std::process::id()
    ));
    std::fs::write(&path, out).unwrap();
    (path, count)
}

#[test]
fn torch_weight_norm_layouts_load_the_same_model() {
    let legacy = load_tiny();
    let codes = read_codes("rand_codes.npy");
    let want: Vec<u32> = legacy
        .decode(&codes)
        .unwrap()
        .iter()
        .map(|v| v.to_bits())
        .collect();
    for layout in [TorchLayout::ConvHop, TorchLayout::Bare] {
        let (path, renamed) = renamed_fixture(layout);
        // A rename that touched nothing would pass without exercising
        // the resolver.
        assert!(renamed > 0, "fixture rename touched no tensors");
        let config = FishS1DacConfig::from_json(&read_json("tiny_config.json")).expect("config");
        let file = SafetensorsFile::open(&path).expect("renamed weights");
        assert!(!file.tensor_names().any(|n| n == "encoder.block.0.weight_v"));
        let model = FishS1Dac::load(config, &file).expect("load torch layout");
        let got: Vec<u32> = model
            .decode(&codes)
            .unwrap()
            .iter()
            .map(|v| v.to_bits())
            .collect();
        assert_eq!(got, want, "decode must be bit-identical across layouts");
        let _ = std::fs::remove_file(&path);
    }
}

/// Random but valid codes, `[books][frames]`: the semantic book draws from
/// its own size, the acoustic books from theirs.
fn random_codes(model: &FishS1Dac, frames: usize, seed: u32) -> Vec<Vec<i32>> {
    let q = &model.config.quantizer;
    let mut state = seed.wrapping_mul(2_654_435_761).wrapping_add(1);
    let mut next = |size: usize| {
        state ^= state << 13;
        state ^= state >> 17;
        state ^= state << 5;
        (state % size as u32) as i32
    };
    (0..model.config.total_books())
        .map(|b| {
            let size = if b == 0 {
                q.semantic_codebook_size
            } else {
                q.codebook_size
            };
            (0..frames).map(|_| next(size)).collect()
        })
        .collect()
}

fn stream_decode(model: &FishS1Dac, codes: &[Vec<i32>], chunks: &[usize]) -> Vec<f32> {
    let mut stream = model.stream();
    let mut out = Vec::new();
    let mut at = 0;
    for &n in chunks.iter().cycle() {
        if at >= codes[0].len() {
            break;
        }
        let end = (at + n).min(codes[0].len());
        let piece: Vec<Vec<i32>> = codes.iter().map(|b| b[at..end].to_vec()).collect();
        out.extend(stream.push(&piece).unwrap());
        at = end;
    }
    assert_eq!(stream.position(), codes[0].len());
    out
}

/// Streaming decode is the whole-sequence decode, bit for bit, across the
/// post transformer's window (4 frames here, so 24 frames cross it several
/// times) and with every conv's carried columns crossing chunk edges (one
/// frame per chunk crosses all of them every time).
#[test]
fn stream_matches_whole_decode() {
    let model = load_tiny();
    let codes = random_codes(&model, 24, 7);
    let whole: Vec<u32> = model
        .decode(&codes)
        .unwrap()
        .iter()
        .map(|v| v.to_bits())
        .collect();
    for chunks in [vec![1], vec![3, 1, 5], vec![7], vec![24]] {
        let got: Vec<u32> = stream_decode(&model, &codes, &chunks)
            .iter()
            .map(|v| v.to_bits())
            .collect();
        assert_eq!(got.len(), whole.len());
        assert_eq!(got, whole, "chunks {chunks:?}");
    }
}

/// A device running the crate's own host kernels, so routing through
/// [`super::DacExec`] (which operations go out, weight layouts, groups,
/// transposed convs) is checked bit for bit, and counted.
mod host_device {
    use crate::backend::{
        AttentionShape, ComputeBackend, ConvShape, DType, DeviceWeight, WeightData,
    };
    use crate::codec::wnconv::snake1d;
    use crate::{ops, Result, SpeechError};
    use std::cell::Cell;
    use std::rc::Rc;

    #[derive(Default)]
    pub(super) struct Counts {
        pub(super) conv: Cell<usize>,
        pub(super) grouped: Cell<usize>,
        pub(super) transposed: Cell<usize>,
        pub(super) linear: Cell<usize>,
        pub(super) snake: Cell<usize>,
        pub(super) uploads: Cell<usize>,
    }

    fn bump(c: &Cell<usize>) {
        c.set(c.get() + 1);
    }

    pub(super) struct HostDevice {
        pub(super) counts: Rc<Counts>,
    }

    struct Weight {
        values: Vec<f32>,
        shape: Vec<usize>,
        counts: Rc<Counts>,
    }

    impl DeviceWeight for Weight {
        fn linear(
            &self,
            x: &[f32],
            bias: Option<&[f32]>,
            rows: usize,
            input: usize,
            output: usize,
            _: DType,
        ) -> Result<Vec<f32>> {
            assert_eq!(self.shape, [output, input]);
            bump(&self.counts.linear);
            Ok(ops::linear(x, &self.values, bias, rows, input, output))
        }
        fn embedding(&self, _: &[i32], _: usize) -> Result<Vec<f32>> {
            Err(SpeechError::Unsupported {
                why: "unused".into(),
            })
        }
        fn convolution(
            &self,
            x: &[f32],
            b: Option<&[f32]>,
            s: ConvShape,
            d: DType,
        ) -> Result<Vec<f32>> {
            self.convolution_grouped(x, b, s, 1, d)
        }
        fn convolution_grouped(
            &self,
            x: &[f32],
            b: Option<&[f32]>,
            s: ConvShape,
            groups: usize,
            _: DType,
        ) -> Result<Vec<f32>> {
            if groups != 1 {
                bump(&self.counts.grouped);
            }
            if s.transpose {
                assert_eq!(
                    self.shape,
                    [s.input_channels, s.output_channels / groups, s.kernel]
                );
                bump(&self.counts.transposed);
                Ok(ops::conv_transpose1d(
                    x,
                    &self.values,
                    b,
                    s.input_channels,
                    s.output_channels,
                    s.kernel,
                    s.stride,
                    s.padding,
                    0,
                    groups,
                ))
            } else {
                assert_eq!(
                    self.shape,
                    [s.output_channels, s.input_channels / groups, s.kernel]
                );
                bump(&self.counts.conv);
                Ok(ops::conv1d(
                    x,
                    &self.values,
                    b,
                    s.input_channels,
                    s.output_channels,
                    s.kernel,
                    s.stride,
                    s.padding,
                    s.dilation,
                    groups,
                ))
            }
        }
    }

    impl ComputeBackend for HostDevice {
        fn load_weight(&self, data: WeightData<'_>) -> Result<Rc<dyn DeviceWeight>> {
            bump(&self.counts.uploads);
            let values = data
                .bytes
                .chunks_exact(4)
                .map(|b| f32::from_le_bytes([b[0], b[1], b[2], b[3]]))
                .collect();
            Ok(Rc::new(Weight {
                values,
                shape: data.shape.to_vec(),
                counts: self.counts.clone(),
            }))
        }
        fn attention(
            &self,
            _: &[f32],
            _: &[f32],
            _: &[f32],
            _: AttentionShape,
            _: DType,
        ) -> Result<Vec<f32>> {
            Err(SpeechError::Unsupported {
                why: "unused".into(),
            })
        }
        /// The host's guarded Snake, not the trait default, so the
        /// comparison stays bit for bit.
        fn snake(
            &self,
            x: &[f32],
            alpha: &[f32],
            channels: usize,
            frames: usize,
            _: DType,
        ) -> Result<Vec<f32>> {
            bump(&self.counts.snake);
            let mut out = x.to_vec();
            snake1d(&mut out, alpha, channels, frames);
            Ok(out)
        }
    }
}

/// Decode, streamed decode and encode through a device exec are the host
/// paths bit for bit, with every conv kind, the pointwise linears and Snake
/// sent out, and each weight uploaded once.
#[test]
fn device_exec_routes_the_heavy_operations() {
    use std::rc::Rc;
    let model = load_tiny();
    let counts = Rc::new(host_device::Counts::default());
    let exec = super::DacExec::device(Rc::new(host_device::HostDevice {
        counts: counts.clone(),
    }));
    let bits = |v: &[f32]| v.iter().map(|x| x.to_bits()).collect::<Vec<_>>();

    let codes = random_codes(&model, 12, 3);
    let host = model.decode(&codes).unwrap();
    assert_eq!(bits(&model.decode_on(&exec, &codes).unwrap()), bits(&host));
    for (name, count) in [
        ("conv", &counts.conv),
        ("grouped", &counts.grouped),
        ("transposed", &counts.transposed),
        ("linear", &counts.linear),
        ("snake", &counts.snake),
    ] {
        assert!(count.get() > 0, "decode sent no {name} to the device");
    }
    let uploads = counts.uploads.get();

    let mut stream = model.stream_on(&exec);
    let mut streamed = Vec::new();
    for piece in [0..5, 5..12] {
        let chunk: Vec<Vec<i32>> = codes.iter().map(|b| b[piece.clone()].to_vec()).collect();
        streamed.extend(stream.push(&chunk).unwrap());
    }
    assert_eq!(
        bits(&streamed),
        bits(&host),
        "streamed decode on the device"
    );
    assert_eq!(
        counts.uploads.get(),
        uploads,
        "decode weights uploaded twice"
    );

    let samples: Vec<f32> = (0..model.config.frame_length() * 3)
        .map(|i| (i as f32 * 0.013).sin() * 0.5)
        .collect();
    let (want, want_len) = model.encode(&samples).unwrap();
    let (got, got_len) = model.encode_on(&exec, &samples).unwrap();
    assert_eq!((got, got_len), (want, want_len), "encode on the device");
}
